1	/**
2	 * bytes.mjs — low-level byte helpers for the pure-JS JOSE port.
3	 *
4	 * Everything in here is hand-rolled plain-JS bit arithmetic on purpose: no
5	 * platform byte containers, no platform text codecs, no builtin modules at all.
6	 * That keeps the whole library provably self-contained and dependency free.
7	 *
8	 * A "byte string" in this library is always a Uint8Array. JavaScript strings are
9	 * UTF-16 code unit sequences, so the encoder below is responsible for pairing
10	 * surrogates back into astral code points before emitting UTF-8.
11	 */
12	
13	/** Bytes of U+FFFD REPLACEMENT CHARACTER, used for every ill-formed sequence. */
14	const REPLACEMENT_BYTES = [0xef, 0xbf, 0xbd];
15	
16	/** U+FFFD as a code unit, emitted by the decoder on malformed input. */
17	const REPLACEMENT_CODE_UNIT = 0xfffd;
18	
19	/** Flush the decoder's code-unit accumulator this often to bound memory/stack. */
20	const STRING_CHUNK_SIZE = 4096;
21	
22	/**
23	 * Encode a JavaScript string to UTF-8 bytes (RFC 3629 well-formed forms only).
24	 *
25	 * - U+0000..U+007F      -> 1 byte  0xxxxxxx
26	 * - U+0080..U+07FF      -> 2 bytes 110xxxxx 10xxxxxx
27	 * - U+0800..U+FFFF      -> 3 bytes 1110xxxx 10xxxxxx 10xxxxxx
28	 * - U+10000..U+10FFFF   -> 4 bytes 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
29	 *   (reached through a well-formed high/low UTF-16 surrogate pair)
30	 *
31	 * An unpaired surrogate (a lone high surrogate, or a low surrogate with no
32	 * preceding high surrogate) is not a valid scalar value, so it is replaced by
33	 * the three bytes of U+FFFD rather than being encoded as CESU-8.
34	 *
35	 * @param {string} str input text
36	 * @returns {Uint8Array} the UTF-8 encoding of `str`
37	 */
38	export function utf8Encode(str) {
39	  const text = typeof str === 'string' ? str : String(str);
40	  const out = [];
41	
42	  for (let i = 0; i < text.length; i += 1) {
43	    let codePoint = text.charCodeAt(i);
44	
45	    // Resolve surrogates into a scalar value before doing any bit work.
46	    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
47	      // High surrogate: only valid when directly followed by a low surrogate.
48	      const next = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
49	      if (next >= 0xdc00 && next <= 0xdfff) {
50	        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + (next - 0xdc00);
51	        i += 1; // the low surrogate is consumed as part of this code point
52	      } else {
53	        pushAll(out, REPLACEMENT_BYTES);
54	        continue;
55	      }
56	    } else if (codePoint >= 0xdc00 && codePoint <= 0xdfff) {
57	      // Lone low surrogate: never valid on its own.
58	      pushAll(out, REPLACEMENT_BYTES);
59	      continue;
60	    }
61	
62	    if (codePoint <= 0x7f) {
63	      out.push(codePoint);
64	    } else if (codePoint <= 0x7ff) {
65	      out.push(0xc0 | (codePoint >> 6));
66	      out.push(0x80 | (codePoint & 0x3f));
67	    } else if (codePoint <= 0xffff) {
68	      out.push(0xe0 | (codePoint >> 12));
69	      out.push(0x80 | ((codePoint >> 6) & 0x3f));
70	      out.push(0x80 | (codePoint & 0x3f));
71	    } else {
72	      out.push(0xf0 | (codePoint >> 18));
73	      out.push(0x80 | ((codePoint >> 12) & 0x3f));
74	      out.push(0x80 | ((codePoint >> 6) & 0x3f));
75	      out.push(0x80 | (codePoint & 0x3f));
76	    }
77	  }
78	
79	  return new Uint8Array(out);
80	}
81	
82	/**
83	 * Decode UTF-8 bytes back into a JavaScript string.
84	 *
85	 * The decoder is strict about well-formedness and substitutes one U+FFFD for
86	 * every maximal ill-formed subsequence (the same policy as the WHATWG encoding
87	 * standard). Rejected and replaced:
88	 *
89	 * - stray continuation bytes (0x80..0xBF) and invalid lead bytes (0xC0, 0xC1,
90	 *   0xF5..0xFF)
91	 * - overlong forms, via the narrowed second-byte range per lead byte
92	 *   (0xE0 needs 0xA0..0xBF, 0xF0 needs 0x90..0xBF, ...)
93	 * - UTF-16 surrogates encoded as 3 bytes (0xED 0xA0..0xBF ...)
94	 * - code points above U+10FFFF (0xF4 only accepts 0x80..0x8F)
95	 * - truncated sequences, including one cut off at the end of the input
96	 *
97	 * When a continuation byte turns out to be invalid it is *not* consumed: it is
98	 * re-examined as a potential lead byte, so "\xE0\x41" decodes to U+FFFD + "A".
99	 *
100	 * @param {Uint8Array|number[]} bytes UTF-8 encoded input
101	 * @returns {string} the decoded text
102	 */
103	export function utf8Decode(bytes) {
104	  const input = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
105	  const pieces = [];
106	  let units = [];
107	  let i = 0;
108	
109	  while (i < input.length) {
110	    const lead = input[i];
111	
112	    // Fast path: plain ASCII is one byte, one code unit.
113	    if (lead <= 0x7f) {
114	      units.push(lead);
115	      i += 1;
116	      units = maybeFlush(pieces, units);
117	      continue;
118	    }
119	
120	    // Work out how many trailing bytes follow and how wide the second byte may
121	    // be. The narrowed lower/upper bounds are what makes overlong sequences,
122	    // surrogates and out-of-range code points fail here instead of silently
123	    // decoding.
124	    let needed = 0;
125	    let lowerBound = 0x80;
126	    let upperBound = 0xbf;
127	    let codePoint = 0;
128	
129	    if (lead >= 0xc2 && lead <= 0xdf) {
130	      needed = 1;
131	      codePoint = lead & 0x1f;
132	    } else if (lead >= 0xe0 && lead <= 0xef) {
133	      needed = 2;
134	      codePoint = lead & 0x0f;
135	      if (lead === 0xe0) {
136	        lowerBound = 0xa0; // reject overlong 3-byte forms of U+0000..U+07FF
137	      } else if (lead === 0xed) {
138	        upperBound = 0x9f; // reject the surrogate range U+D800..U+DFFF
139	      }
140	    } else if (lead >= 0xf0 && lead <= 0xf4) {
141	      needed = 3;
142	      codePoint = lead & 0x07;
143	      if (lead === 0xf0) {
144	        lowerBound = 0x90; // reject overlong 4-byte forms of U+0000..U+FFFF
145	      } else if (lead === 0xf4) {
146	        upperBound = 0x8f; // reject code points above U+10FFFF
147	      }
148	    } else {
149	      // 0x80..0xC1 and 0xF5..0xFF can never start a sequence.
150	      units.push(REPLACEMENT_CODE_UNIT);
151	      i += 1;
152	      units = maybeFlush(pieces, units);
153	      continue;
154	    }
155	
156	    let consumed = 1;
157	    let valid = true;
158	
159	    for (let n = 0; n < needed; n += 1) {
160	      const index = i + 1 + n;
161	      const byte = index < input.length ? input[index] : -1;
162	      const min = n === 0 ? lowerBound : 0x80;
163	      const max = n === 0 ? upperBound : 0xbf;
164	
165	      if (byte < min || byte > max) {
166	        // Truncated or invalid: emit one U+FFFD for the maximal subpart we saw
167	        // and leave the offending byte for the next iteration.
168	        valid = false;
169	        break;
170	      }
171	
172	      codePoint = (codePoint << 6) | (byte & 0x3f);
173	      consumed += 1;
174	    }
175	
176	    if (!valid) {
177	      units.push(REPLACEMENT_CODE_UNIT);
178	      i += consumed;
179	      units = maybeFlush(pieces, units);
180	      continue;
181	    }
182	
183	    i += consumed;
184	
185	    if (codePoint <= 0xffff) {
186	      units.push(codePoint);
187	    } else {
188	      // Split the astral code point back into a UTF-16 surrogate pair.
189	      const offset = codePoint - 0x10000;
190	      units.push(0xd800 + (offset >> 10));
191	      units.push(0xdc00 + (offset & 0x3ff));
192	    }
193	
194	    units = maybeFlush(pieces, units);
195	  }
196	
197	  if (units.length > 0) {
198	    pieces.push(String.fromCharCode.apply(null, units));
199	  }
200	
201	  return pieces.join('');
202	}
203	
204	/**
205	 * Encode a string as latin-1 / binary bytes: keep only the low byte of every
206	 * UTF-16 code unit. Used where a "byte string" is already held in a JS string
207	 * (base64 intermediates, raw signature material) and no transcoding is wanted.
208	 *
209	 * @param {string} str input whose code units are treated as byte values
210	 * @returns {Uint8Array} one byte per input code unit
211	 */
212	export function latin1Encode(str) {
213	  const text = typeof str === 'string' ? str : String(str);
214	  const out = new Uint8Array(text.length);
215	  for (let i = 0; i < text.length; i += 1) {
216	    out[i] = text.charCodeAt(i) & 0xff;
217	  }
218	  return out;
219	}
220	
221	/**
222	 * Concatenate a list of byte arrays into one fresh Uint8Array.
223	 *
224	 * @param {Array<Uint8Array|number[]>} list byte arrays to join, in order
225	 * @returns {Uint8Array} the concatenation
226	 */
227	export function concatBytes(list) {
228	  const parts = (list || []).map((part) =>
229	    part instanceof Uint8Array ? part : new Uint8Array(part || [])
230	  );
231	
232	  let total = 0;
233	  for (const part of parts) {
234	    total += part.length;
235	  }
236	
237	  const out = new Uint8Array(total);
238	  let offset = 0;
239	  for (const part of parts) {
240	    out.set(part, offset);
241	    offset += part.length;
242	  }
243	  return out;
244	}
245	
246	/**
247	 * Plain (non-timing-safe) byte comparison. Use this for structural checks only;
248	 * signature comparison goes through the timing-safe helper in hmac.mjs.
249	 *
250	 * @param {Uint8Array|number[]} a first operand
251	 * @param {Uint8Array|number[]} b second operand
252	 * @returns {boolean} true when both have the same length and the same bytes
253	 */
254	export function bytesEqual(a, b) {
255	  const left = a instanceof Uint8Array ? a : new Uint8Array(a || []);
256	  const right = b instanceof Uint8Array ? b : new Uint8Array(b || []);
257	
258	  if (left.length !== right.length) {
259	    return false;
260	  }
261	  for (let i = 0; i < left.length; i += 1) {
262	    if (left[i] !== right[i]) {
263	      return false;
264	    }
265	  }
266	  return true;
267	}
268	
269	/**
270	 * Append every element of `src` to `dst` (small helper to keep the encoder
271	 * loop free of spread allocations).
272	 *
273	 * @param {number[]} dst accumulator being appended to
274	 * @param {number[]} src values to append
275	 */
276	function pushAll(dst, src) {
277	  for (let i = 0; i < src.length; i += 1) {
278	    dst.push(src[i]);
279	  }
280	}
281	
282	/**
283	 * Turn the decoder's code-unit accumulator into a string chunk once it grows
284	 * past STRING_CHUNK_SIZE, so `String.fromCharCode.apply` never sees an argument
285	 * list large enough to overflow the call stack.
286	 *
287	 * @param {string[]} pieces collected string chunks
288	 * @param {number[]} units pending UTF-16 code units
289	 * @returns {number[]} the accumulator to keep using (empty after a flush)
290	 */
291	function maybeFlush(pieces, units) {
292	  if (units.length >= STRING_CHUNK_SIZE) {
293	    pieces.push(String.fromCharCode.apply(null, units));
294	    return [];
295	  }
296	  return units;
297	}
