/**
 * pyjson.mjs — a byte-faithful reimplementation of the two CPython `json`
 * entry points this port needs:
 *
 *   pyJsonDumpsCompact(value)  ==  json.dumps(value, separators=(',', ':'))
 *                                  with the default ensure_ascii=True
 *   pyJsonLoads(text)          ==  json.loads(text)
 *
 * Why hand-written instead of JSON.stringify / JSON.parse:
 *
 * 1. `JSON.stringify` leaves every printable non-ASCII character raw, while
 *    CPython escapes anything outside 0x20..0x7e (so U+4E2D becomes 中 and
 *    U+007F becomes ). The JWT payload must match the reference bytes
 *    exactly, because the signature is computed over them.
 * 2. `JSON.parse` returns plain objects, which silently reorder integer-like
 *    keys ({"2":1,"1":2} comes back as {1:2, 2:1}). Python dicts preserve
 *    insertion order and the decoded-claims line printed by the program is a
 *    dict repr, so order is observable. Objects are therefore returned as
 *    `Map` instances.
 * 3. Python distinguishes `int` from `float`: repr(1) is "1" but repr(1.0) is
 *    "1.0". JSON.parse collapses both into one Number. See "Float tagging".
 *
 * ── Float tagging ────────────────────────────────────────────────────────────
 * `isJsonInteger(value)` is the discriminator pyrepr.mjs uses to pick between
 * Python int and Python float formatting. The rules are:
 *
 *   - A plain Number that is an integer value (Number.isInteger) counts as a
 *     Python int, and so does a BigInt.
 *   - A plain Number with a fractional part, NaN or ±Infinity is already
 *     unambiguously a Python float, so it needs no extra bookkeeping.
 *   - The only ambiguous case is a JSON *float literal whose value happens to
 *     be integral* — "1.0", "2e3", "-0.0". Those, and only those, are returned
 *     wrapped in the exported `PyFloat` marker class, whose `isJsonInteger` is
 *     false and whose `toString()` already yields the Python repr ("1.0").
 *
 * Wrapping is kept to that minimum on purpose: every other value stays a
 * primitive Number, so consumers that only understand primitives keep working.
 * `PyFloat` defines `valueOf()`, so arithmetic and comparisons still behave.
 * (The payloads this program handles — a string plus an integer `iat` — never
 * contain a float at all, so in practice no marker is ever produced.)
 *
 * Integers are returned as Numbers per the module contract. A JSON integer
 * larger than 2**53-1 therefore loses precision, exactly where Python would
 * have kept an arbitrary-precision int; the serialiser, however, still writes
 * large integral Numbers back out as exact digits (never "1e+21").
 */

import { utf8Decode } from './bytes.mjs';

/** Characters CPython's json module treats as whitespace between tokens. */
const WHITESPACE = ' \t\n\r';

/** Escapes CPython emits for these code points instead of a \uXXXX form. */
const SHORT_ESCAPES = new Map([
  [0x08, '\\b'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0c, '\\f'],
  [0x0d, '\\r'],
]);

/** Reverse table for the one-character escapes accepted by the parser. */
const SIMPLE_UNESCAPES = new Map([
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['b', '\b'],
  ['f', '\f'],
  ['n', '\n'],
  ['r', '\r'],
  ['t', '\t'],
]);

/** JSON number grammar, anchored so it can be applied at an offset. */
const NUMBER_PATTERN = /-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?/y;

/** Exactly four hex digits, for \uXXXX escapes. */
const HEX4_PATTERN = /^[0-9a-fA-F]{4}$/;

/**
 * CPython switches float repr to scientific notation when the decimal point
 * position is <= -4 or > 16. Expressed against the exponent of the normalised
 * mantissa (value = d.ddd * 10**exp) that is exp <= -5 or exp > 15.
 */
const FLOAT_EXP_LOW = -5;
const FLOAT_EXP_HIGH = 15;

/**
 * Marker for a Python float whose value happens to be integral ("1.0", "2e3").
 *
 * Only the parser creates these, and only for that ambiguous case; see the
 * "Float tagging" note at the top of the file.
 */
export class PyFloat {
  /**
   * @param {number} value the numeric value (must be finite and integral to be
   *   worth marking, though any number is accepted)
   */
  constructor(value) {
    /** @type {number} */
    this.value = Number(value);
  }

  /** Let arithmetic, comparisons and Number() see through the wrapper. */
  valueOf() {
    return this.value;
  }

  /** String coercion yields the Python float repr, e.g. "1.0" / "-0.0". */
  toString() {
    return pythonFloatRepr(this.value);
  }

  /** Keep the wrapper transparent to the builtin JSON serialiser too. */
  toJSON() {
    return this.value;
  }
}

/**
 * Python's json.JSONDecodeError: a ValueError carrying the failure position.
 * The `message` is formatted exactly like CPython's, e.g.
 * "Expecting value: line 1 column 1 (char 0)".
 */
export class JSONDecodeError extends Error {
  /**
   * @param {string} msg the bare reason, without position information
   * @param {string} doc the document being parsed
   * @param {number} pos zero-based offset of the offending character
   */
  constructor(msg, doc, pos) {
    const lineno = countNewlines(doc, pos) + 1;
    const colno = pos - doc.lastIndexOf('\n', pos - 1);
    super(`${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.name = 'JSONDecodeError';
    /** @type {string} the reason without position, like CPython's `.msg` */
    this.msg = msg;
    /** @type {string} */
    this.doc = doc;
    /** @type {number} */
    this.pos = pos;
    /** @type {number} */
    this.lineno = lineno;
    /** @type {number} */
    this.colno = colno;
  }
}

/**
 * Serialise a value the way `json.dumps(value, separators=(',', ':'))` does:
 * no whitespace after ':' or ',', and ensure_ascii=True so every code unit
 * outside 0x20..0x7e is escaped.
 *
 * Accepted inputs: Map (preferred — preserves key order), plain object, Array,
 * string, number, BigInt, PyFloat, boolean, null and undefined (like None).
 *
 * @param {*} value the value to serialise
 * @returns {string} the compact JSON text
 * @throws {TypeError} for a value (or dict key) Python could not serialise
 * @throws {Error} when the value graph contains a cycle
 */
export function pyJsonDumpsCompact(value) {
  return serialise(value, new Set());
}

/**
 * Parse JSON text into Python-shaped values.
 *
 * Mapping: object -> Map (insertion ordered), array -> Array, string -> string,
 * integer literal -> Number, float literal -> Number or PyFloat (see the
 * "Float tagging" note), true/false -> boolean, null -> null. The non-standard
 * constants CPython accepts by default — NaN, Infinity, -Infinity — are
 * accepted too and yield the matching JS numbers.
 *
 * @param {string|Uint8Array|number[]} text JSON document; byte input is decoded
 *   as UTF-8 first, matching json.loads(bytes)
 * @returns {*} the parsed value
 * @throws {JSONDecodeError} on malformed input, with CPython's message
 * @throws {TypeError} when `text` is not text or bytes
 */
export function pyJsonLoads(text) {
  const doc = coerceDocument(text);

  // CPython rejects a byte-order mark up front rather than at the value scan.
  if (doc.charCodeAt(0) === 0xfeff) {
    throw new JSONDecodeError('Unexpected UTF-8 BOM (decode using utf-8-sig)', doc, 0);
  }

  const state = { doc, pos: 0 };
  skipWhitespace(state);
  const value = parseValue(state);
  skipWhitespace(state);

  if (state.pos < doc.length) {
    throw new JSONDecodeError('Extra data', doc, state.pos);
  }
  return value;
}

/**
 * Would Python have called this value an `int`?
 *
 * True for integral Numbers and BigInts; false for PyFloat markers, for
 * fractional/NaN/Infinite Numbers, and for everything that is not a number.
 *
 * @param {*} value candidate value
 * @returns {boolean} true when the value should be repr'd as a Python int
 */
export function isJsonInteger(value) {
  if (typeof value === 'bigint') {
    return true;
  }
  if (value instanceof PyFloat) {
    return false;
  }
  return typeof value === 'number' && Number.isInteger(value);
}

/**
 * Complement of {@link isJsonInteger} restricted to numeric values: true for
 * PyFloat markers and for Numbers Python would print with a decimal point or
 * as inf/nan.
 *
 * @param {*} value candidate value
 * @returns {boolean} true when the value should be repr'd as a Python float
 */
export function isJsonFloat(value) {
  if (value instanceof PyFloat) {
    return true;
  }
  return typeof value === 'number' && !Number.isInteger(value);
}

/**
 * Unwrap a PyFloat marker (or pass a plain number through), so callers never
 * have to special-case the marker when they only want the numeric value.
 *
 * @param {*} value number, BigInt or PyFloat
 * @returns {number} the numeric value
 */
export function jsonNumberValue(value) {
  if (value instanceof PyFloat) {
    return value.value;
  }
  if (typeof value === 'bigint') {
    return Number(value);
  }
  return Number(value);
}

/**
 * Format a JS number the way `repr()` formats a Python float: shortest
 * round-tripping digits, always a decimal point or an exponent, exponents
 * signed and zero-padded to at least two digits ("1e-07", "1e+16").
 *
 * @param {number} value the float to render
 * @returns {string} the Python-style repr
 */
export function pythonFloatRepr(value) {
  const number = Number(value);

  if (Number.isNaN(number)) {
    return 'nan';
  }
  if (number === Infinity) {
    return 'inf';
  }
  if (number === -Infinity) {
    return '-inf';
  }

  // Object.is catches -0, whose toExponential() drops the sign.
  const negative = number < 0 || Object.is(number, -0);
  const magnitude = negative ? -number : number;

  // toExponential() with no argument gives the shortest digit string that
  // uniquely identifies the double — the same digits CPython's repr uses.
  const scientific = magnitude.toExponential();
  const eIndex = scientific.indexOf('e');
  const digits = scientific.slice(0, eIndex).replace('.', '');
  const exponent = Number(scientific.slice(eIndex + 1));

  const body =
    exponent <= FLOAT_EXP_LOW || exponent > FLOAT_EXP_HIGH
      ? formatFloatScientific(digits, exponent)
      : formatFloatPositional(digits, exponent);

  return negative ? `-${body}` : body;
}

/* ────────────────────────────── serialiser ────────────────────────────── */

/**
 * Recursive worker behind {@link pyJsonDumpsCompact}.
 *
 * @param {*} value value to serialise
 * @param {Set<object>} active containers currently on the recursion stack,
 *   used for CPython's check_circular behaviour
 * @returns {string} JSON text for `value`
 */
function serialise(value, active) {
  if (value === null || value === undefined) {
    return 'null'; // Python None
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'string') {
    return encodeJsonStringAscii(value);
  }
  if (typeof value === 'number') {
