/* ──────────────────────────────── parser ──────────────────────────────── */

/**
 * Accept text, or UTF-8 bytes like `json.loads(b'...')` does.
 *
 * @param {string|Uint8Array|number[]} text input document
 * @returns {string} the document as text
 */
function coerceDocument(text) {
  if (typeof text === 'string') {
    return text;
  }
  if (text instanceof Uint8Array) {
    return utf8Decode(text);
  }
  if (Array.isArray(text)) {
    return utf8Decode(new Uint8Array(text));
