/**
 * Advance past JSON whitespace.
 *
 * @param {{doc: string, pos: number}} state scanner state, mutated in place
 */
function skipWhitespace(state) {
  const { doc } = state;
  let i = state.pos;
  while (i < doc.length && WHITESPACE.indexOf(doc[i]) !== -1) {
    i += 1;
  }
  state.pos = i;
