  const ch = pos < doc.length ? doc[pos] : '';

  switch (ch) {
    case '"':
      return parseString(state);
    case '{':
      return parseObject(state);
    case '[':
      return parseArray(state);
    default:
      break;
  }

  if (doc.startsWith('true', pos)) {
    state.pos = pos + 4;
    return true;
  }
  if (doc.startsWith('false', pos)) {
    state.pos = pos + 5;
    return false;
  }
  if (doc.startsWith('null', pos)) {
    state.pos = pos + 4;
    return null;
  }

  // CPython's default parse_constant accepts these three spellings.
  if (doc.startsWith('NaN', pos)) {
    state.pos = pos + 3;
    return NaN;
  }
  if (doc.startsWith('Infinity', pos)) {
    state.pos = pos + 8;
    return Infinity;
  }
  if (doc.startsWith('-Infinity', pos)) {
