/**
 * Parse a JSON number, distinguishing Python's int from float by the literal's
 * shape rather than by its value.
 *
 * @param {{doc: string, pos: number}} state scanner state, mutated in place
 * @returns {number|PyFloat} an integral Number, a fractional Number, or a
 *   PyFloat marker for a float literal with an integral value
 */
function parseNumber(state) {
