  if (!match || match.index !== pos) {
    throw new JSONDecodeError('Expecting value', doc, pos);
  }

  const literal = match[0];
  const hasFraction = match[1] !== undefined;
  const hasExponent = match[2] !== undefined;
  state.pos = pos + literal.length;

  if (!hasFraction && !hasExponent) {
    // Integer literal: normalise "-0" to 0, since Python's int has no -0.
    const asInteger = Number(literal);
    return asInteger === 0 ? 0 : asInteger;
  }

  const asFloat = Number(literal);

  // Only an integral float value needs the marker; anything else is already
  // recognisable as a float by its value alone.
  if (Number.isFinite(asFloat) && Number.isInteger(asFloat)) {
    return new PyFloat(asFloat);
  }
  return asFloat;
