/**
 * Parse a quoted string starting at the opening double quote.
 *
 * Escapes handled: \" \\ \/ \b \f \n \r \t and \uXXXX. A \uXXXX surrogate pair
 * needs no special casing — appending both code units to a JS string already
 * yields the astral character Python builds. Unescaped control characters are
 * rejected, matching json.loads' strict=True default.
 *
 * @param {{doc: string, pos: number}} state scanner state, mutated in place
 * @returns {string} the decoded string
 */
function parseString(state) {
  const { doc } = state;
  const start = state.pos; // index of the opening quote
  let i = start + 1;
  let chunkStart = i;
  let out = '';

  for (;;) {
    if (i >= doc.length) {
      throw new JSONDecodeError('Unterminated string starting at', doc, start);
    }

    const code = doc.charCodeAt(i);

    if (code === 0x22) {
      out += doc.slice(chunkStart, i);
      i += 1;
      break;
    }

    if (code === 0x5c) {
      out += doc.slice(chunkStart, i);
      i += 1;
      if (i >= doc.length) {
        throw new JSONDecodeError('Unterminated string starting at', doc, start);
      }

