        if (decoded === undefined) {
          throw new JSONDecodeError('Invalid \\escape', doc, i - 1);
        }
        out += decoded;
        i += 1;
      }

      chunkStart = i;
      continue;
    }

    if (code < 0x20) {
      throw new JSONDecodeError('Invalid control character at', doc, i);
    }

    i += 1;
  }

