  return out;
}

/**
 * Parse an object starting at '{' into a Map, so key insertion order survives.
 * A repeated key updates the existing entry in place, exactly like a Python
 * dict (and like Map.set).
 *
 * @param {{doc: string, pos: number}} state scanner state, mutated in place
 * @returns {Map<string, *>} the parsed object
 */
function parseObject(state) {
  const { doc } = state;
  const result = new Map();

  state.pos += 1; // consume '{'
  skipWhitespace(state);

  if (doc[state.pos] === '}') {
    state.pos += 1;
    return result;
  }

  for (;;) {
    if (doc[state.pos] !== '"') {
      throw new JSONDecodeError(
        'Expecting property name enclosed in double quotes',
        doc,
        state.pos
      );
    }

    const key = parseString(state);

    skipWhitespace(state);
    if (doc[state.pos] !== ':') {
      throw new JSONDecodeError("Expecting ':' delimiter", doc, state.pos);
    }
    state.pos += 1;

    skipWhitespace(state);
    result.set(key, parseValue(state));

    skipWhitespace(state);
    const ch = doc[state.pos];

    if (ch === '}') {
      state.pos += 1;
      return result;
    }
    if (ch !== ',') {
      throw new JSONDecodeError("Expecting ',' delimiter", doc, state.pos);
    }

    state.pos += 1;
    skipWhitespace(state);
  }
}

/**
 * Parse an array starting at '['.
 *
 * @param {{doc: string, pos: number}} state scanner state, mutated in place
 * @returns {Array<*>} the parsed list
 */
function parseArray(state) {
  const { doc } = state;
  const result = [];

  state.pos += 1; // consume '['
  skipWhitespace(state);

  if (doc[state.pos] === ']') {
    state.pos += 1;
    return result;
  }

  for (;;) {
    result.push(parseValue(state));

    skipWhitespace(state);
    const ch = doc[state.pos];

    if (ch === ']') {
      state.pos += 1;
      return result;
    }
    if (ch !== ',') {
      throw new JSONDecodeError("Expecting ',' delimiter", doc, state.pos);
    }

    state.pos += 1;
    skipWhitespace(state);
  }
}

/**
 * Count newlines in doc[0:pos], for JSONDecodeError line numbers.
 *
 * @param {string} doc the document
 * @param {number} pos exclusive upper bound
 * @returns {number} number of '\n' characters before `pos`
 */
function countNewlines(doc, pos) {
  let count = 0;
  const limit = Math.min(pos, doc.length);
  for (let i = 0; i < limit; i += 1) {
    if (doc.charCodeAt(i) === 0x0a) {
      count += 1;
    }
  }
  return count;
}

