// Scratch helper: compare my serialiser against the payload bytes the reference
// executable actually signed.  argv: <data> <token>
import { pyJsonDumpsCompact, pyJsonLoads } from '/output/lib/pyjson.mjs';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

/** base64url -> latin1 text (the payload JSON is pure ASCII by construction). */
function b64urlToText(input) {
  let bits = 0;
  let acc = 0;
  let out = '';
  for (const ch of input) {
    const v = ALPHABET.indexOf(ch);
    if (v < 0) continue;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out += String.fromCharCode((acc >> bits) & 0xff);
    }
  }
  return out;
}

const [data, token] = process.argv.slice(2);
const actual = b64urlToText(token.split('.')[1]);
const claims = pyJsonLoads(actual);
const rebuilt = pyJsonDumpsCompact(new Map([['info', data], ['iat', claims.get('iat')]]));

const headerActual = b64urlToText(token.split('.')[0]);
const headerRebuilt = pyJsonDumpsCompact(new Map([['alg', 'HS256'], ['typ', 'JWT']]));

const okPayload = rebuilt === actual;
const okHeader = headerRebuilt === headerActual;
const okInfo = claims.get('info') === data;
const okKeys = [...claims.keys()].join(',') === 'info,iat';

console.log(`${okPayload && okHeader && okInfo && okKeys ? 'OK  ' : 'FAIL'} payload=${actual}`);
if (!okPayload) console.log(`     rebuilt=${rebuilt}`);
if (!okHeader) console.log(`     header actual=${headerActual} rebuilt=${headerRebuilt}`);
if (!okInfo) console.log(`     info mismatch: ${JSON.stringify(claims.get('info'))} vs ${JSON.stringify(data)}`);
if (!okKeys) console.log(`     key order: ${[...claims.keys()].join(',')}`);

