// Scratch differential harness: reads one JSON-encoded case per line from stdin
//   [kind, doc]  where kind is "dumps" (doc = input string) or "loads" (doc = document)
// and prints the result my module produces, one line per case, JSON encoded:
//   ["ok", result] | ["err", message]
import { pyJsonDumpsCompact, pyJsonLoads } from '/output/lib/pyjson.mjs';

let buffer = '';
process.stdin.setEncoding('utf8');
for await (const chunk of process.stdin) {
  buffer += chunk;
}

const out = [];
for (const line of buffer.split('\n')) {
  if (!line) continue;
  const [kind, doc] = JSON.parse(line);
  try {
    if (kind === 'dumps') {
      out.push(JSON.stringify(['ok', pyJsonDumpsCompact(doc)]));
    } else {
      out.push(JSON.stringify(['ok', pyJsonDumpsCompact(pyJsonLoads(doc))]));
    }
  } catch (err) {
    out.push(JSON.stringify(['err', err.message]));
  }
}
console.log(out.join('\n'));

